#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, sz;

    DSU(int n) {
        p.resize(n + 1);
        sz.assign(n + 1, 1);
        iota(p.begin(), p.end(), 0);
    }

    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> adj(N + 1);
    vector<pair<int, int>> edges;
    edges.reserve(M);

    DSU dsu(N);

    for (int i = 0; i < M; i++) {
        int x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);
        edges.emplace_back(x, y);
        dsu.unite(x, y);
    }

    vector<int> compSize(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        compSize[dsu.find(i)]++;
    }

    vector<long long> edgeCnt(N + 1, 0);
    for (auto [x, y] : edges) {
        int r = dsu.find(x);
        edgeCnt[r]++;
    }

    int root = -1;
    int sizeRoot = 0;

    for (int i = 1; i <= N; i++) {
        if (compSize[i] > 1) {
            long long s = compSize[i];
            long long completeEdges = s * (s - 1) / 2;
            if (edgeCnt[i] < completeEdges) {
                root = i;
                sizeRoot = compSize[i];
                break;
            }
        }
    }

    if (root == -1) {
        cout << -1 << '\n';
        return 0;
    }

    int v = -1;
    for (int i = 1; i <= N; i++) {
        if (dsu.find(i) == root && (int)adj[i].size() < sizeRoot - 1) {
            v = i;
            break;
        }
    }

    vector<int> marked(N + 1, 0);
    int token = 1;
    for (int u : adj[v]) {
        marked[u] = token;
    }

    for (int u = 1; u <= N; u++) {
        if (u != v && dsu.find(u) == root && marked[u] != token) {
            cout << v << ' ' << u << '\n';
            return 0;
        }
    }

    cout << -1 << '\n';
    return 0;
}
